import { expect, test } from "bun:test";
import { readFileSync } from "node:fs";

// icons.js is generated by scripts/vendor-lucide.ts. Every icon must carry exactly the
// shapes (with all attributes) of its vendored SVG, and the CSS mask rules must match.
test("generated icon data matches the vendored Lucide files", () => {
  const source = readFileSync(new URL("./icons.js", import.meta.url), "utf8");
  const css = readFileSync(new URL("./design-system.css", import.meta.url), "utf8");
  const entries = [...source.matchAll(/^  "([a-z0-9-]+)": (\[.*\]),$/gm)];
  expect(entries.length).toBeGreaterThan(80);
  for (const [, name, data] of entries) {
    const nodes = JSON.parse(data) as [string, Record<string, string>][];
    const svg = readFileSync(new URL(`./vendor/lucide/${name}.svg`, import.meta.url), "utf8");
    const shapes = [...svg.matchAll(/<(path|circle|rect|line|polyline|polygon|ellipse)\b([^>]*?)\/?>/g)];
    expect(nodes.length).toBe(shapes.length);
    shapes.forEach(([, tag, attrs], index) => {
      expect(nodes[index][0]).toBe(tag);
      for (const [, key] of attrs.matchAll(/([a-zA-Z][a-zA-Z0-9:-]*)="/g)) expect(nodes[index][1]).toHaveProperty(key);
    });
    expect(css).toContain(`.ds-icon[data-icon='${name}'] { --icon: url('/vendor/lucide/${name}.svg'); }`);
  }
});
